--============================================================
-- VHub (VexHub) — ALL IN ONE
-- Главное окно + кнопка открытия + лоадер в одном скрипте.
-- Вставь в LocalScript (StarterPlayerScripts) — всё соберётся само.
-- Гуи строится в PlayerGui.
--============================================================

local Players = game:GetService("Players")
local __parentGui = Players.LocalPlayer:WaitForChild("PlayerGui")

local function c(cls, props)
	local inst = Instance.new(cls)
	for k, v in pairs(props) do
		if k ~= "Parent" then
			inst[k] = v
		end
	end
	if props.Parent ~= nil then
		inst.Parent = props.Parent
	end
	return inst
end

local __moduleLoaders = {}
local __moduleCache = {}
local function __hubRequire(inst)
	if __moduleCache[inst] == nil then
		local loader = __moduleLoaders[inst]
		if loader == nil then
			error("module not found: " .. tostring(inst), 2)
		end
		__moduleCache[inst] = loader()
	end
	return __moduleCache[inst]
end

local function __runLocal(inst, fn)
	task.defer(function()
		local ok, err = pcall(fn, inst)
		if not ok then
			warn("[VHub] script " .. inst:GetFullName() .. ": " .. tostring(err))
		end
	end)
end


