__moduleLoaders[Animation] = function()
local script = Animation
local TweenService = game:GetService("TweenService")

local gui = script.Parent                         -- ScreenGui "VexHub"
local main = gui:WaitForChild("MainWindow")
local content = main:WaitForChild("Content")
local sidebar = gui:FindFirstChild("Scrolling Frame")        -- табы
local topbar = gui:FindFirstChild("Discord, Close and Settings")
local playerBar = gui:FindFirstChild("Player Name And Avatar")

if not sidebar then warn("[VHub] не найден сайдбар 'Scrolling Frame'") end
if not topbar then warn("[VHub] не найдена шапка 'Discord, Close and Settings'") end
if not playerBar then warn("[VHub] не найдена панель 'Player Name And Avatar'") end

local T1 = 0.25 -- скроллы + табы
local T2 = 0.2  -- шапка + панель игрока
local T3 = 0.3  -- окно MainWindow

-- запоминаем оригинальные прозрачности СРАЗУ (на старте они исходные),
-- новые элементы (клоны избранного) подхватываются лениво
local originals = {}

local function capture(inst)
	local props = {}
	if inst:IsA("GuiObject") then
		props.BackgroundTransparency = inst.BackgroundTransparency
		if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
			props.TextTransparency = inst.TextTransparency
		end
		if inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
			props.ImageTransparency = inst.ImageTransparency
		end
		if inst:IsA("ScrollingFrame") then
			props.ScrollBarImageTransparency = inst.ScrollBarImageTransparency
		end
	elseif inst:IsA("UIStroke") then
		props.Transparency = inst.Transparency
	end
	if next(props) then
		originals[inst] = props
		return props
	end
	return nil
end

for _, v in gui:GetDescendants() do
	capture(v)
end

local function applyProps(inst, mode, t)
	local orig = originals[inst] or capture(inst)
	if not orig then return end
	local props = {}
	for name, value in pairs(orig) do
		props[name] = (mode == "out") and 1 or value
	end
	if t and t > 0 then
		TweenService:Create(inst, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
	else
		for name, value in pairs(props) do
			inst[name] = value
		end
	end
end

local function fadeGroup(root, mode, t, exclude)
	if not root then return end
	applyProps(root, mode, t)
	for _, v in root:GetDescendants() do
		if not (exclude and v:IsDescendantOf(exclude)) then
			applyProps(v, mode, t)
		end
	end
end

local anim = {}
local animating = false
local isOpen = gui.Enabled

function anim.open()
	if animating or isOpen then return end
	animating = true
	isOpen = true
	print("[VHub] открытие: окно")

	gui.Enabled = true
	fadeGroup(gui, "out", 0)

	fadeGroup(main, "in", T3, content)
	task.wait(T3)
	print("[VHub] открытие: шапка")
	fadeGroup(topbar, "in", T2)
	fadeGroup(playerBar, "in", T2)
	task.wait(T2)
	print("[VHub] открытие: контент и табы")
	fadeGroup(content, "in", T1)
	fadeGroup(sidebar, "in", T1)
	task.wait(T1)

	-- самолечение: жёстко выставляем финальные прозрачности,
	-- даже если какой-то твин по дороге сдох
	fadeGroup(gui, "in", 0)

	animating = false
	print("[VHub] открыто")
end

function anim.close()
	if animating or not isOpen then return end
	animating = true
	isOpen = false
	print("[VHub] закрытие: контент и табы")

	fadeGroup(content, "out", T1)
	fadeGroup(sidebar, "out", T1)
	task.wait(T1)
	fadeGroup(topbar, "out", T2)
	fadeGroup(playerBar, "out", T2)
	task.wait(T2)
	fadeGroup(main, "out", T3, content)
	task.wait(T3)

	gui.Enabled = false
	fadeGroup(gui, "in", 0)

	animating = false
	print("[VHub] закрыто")
end

function anim.toggle()
	if isOpen then anim.close() else anim.open() end
end

return anim

end

__runLocal(CardsLogic, function(script)
local content = script.Parent

local SEL_STROKE   = Color3.fromRGB(255, 255, 255) -- обводка выбранной карточки
local IDLE_STROKE  = Color3.fromRGB(111, 111, 111)
local FAV_ON       = Color3.fromRGB(255, 200, 40)  -- звезда активного избранного
local FAV_OFF      = Color3.fromRGB(255, 255, 255)

local FAV_PAGE = "Favorites"

local favorites = {} -- [key] = true
local selected  = {} -- [pageName] = card

local function plain(text)
	return (text:gsub("<.->", ""))
end

local function getScroll(page)
	local wrap = page:FindFirstChild("Scrolling Frame")
	return wrap and wrap:FindFirstChildWhichIsA("ScrollingFrame")
end

local function getDetails(page)
	return page:FindFirstChild("Description, Execute etc")
end

local function setLabel(details, name, value)
	local l = details and details:FindFirstChild(name)
	if l and (l:IsA("TextLabel") or l:IsA("TextButton")) then
		l.Text = value
	end
end

local function cardKey(page, card)
	return card:GetAttribute("FavKey") or (page.Name .. "/" .. card.Name)
end

local function updateFavButton(page)
	local btn = page:FindFirstChild("FavoriteButton", true)
	if not btn then return end
	local card = selected[page.Name]
	local on = card and favorites[cardKey(page, card)]
	btn.ImageColor3 = on and FAV_ON or FAV_OFF
end

local function fillDetails(page, card)
	local d = getDetails(page)
	if not d then return end
	local title = card:FindFirstChild("Title")
	setLabel(d, "ScriptName", title and plain(title.Text) or card.Name)
	local idl = card:FindFirstChild("IdLabel")
	local idText = idl and idl.Text or ""
	setLabel(d, "ScriptId1000", idText:match("%d+") or idText)
end

local function selectCard(page, card)
	local prev = selected[page.Name]
	if prev and prev ~= card then
		local st = prev:FindFirstChildWhichIsA("UIStroke")
		if st then st.Color = IDLE_STROKE end
	end
	selected[page.Name] = card
	local st = card:FindFirstChildWhichIsA("UIStroke")
	if st then st.Color = SEL_STROKE end
	fillDetails(page, card)
	updateFavButton(page)
end

local function wireCard(page, card)
	local btn = card:FindFirstChild("Select")
	if btn and btn:IsA("GuiButton") then
		btn.Activated:Connect(function()
			selectCard(page, card)
		end)
	end
end

local function toggleFavorite(page)
	local card = selected[page.Name]
	if not card then return end
	local key = cardKey(page, card)
	local favPage = content:FindFirstChild(FAV_PAGE)
	local favScroll = favPage and getScroll(favPage)

	if favorites[key] then
		-- убрать из избранного
		favorites[key] = nil
		if favScroll then
			for _, c in favScroll:GetChildren() do
				if c:IsA("GuiObject") and c:GetAttribute("FavKey") == key then
					c:Destroy()
				end
			end
		end
		if page.Name == FAV_PAGE then
			selected[page.Name] = nil
		end
	else
		-- добавить: клонируем карточку во вкладку Favorites
		favorites[key] = true
		if favScroll and page.Name ~= FAV_PAGE then
			local clone = card:Clone()
			clone:SetAttribute("FavKey", key)
			clone.Visible = true
			clone.Parent = favScroll
			wireCard(favPage, clone)
		end
	end
	updateFavButton(page)
end

-- обвязка всех страниц
for _, page in content:GetChildren() do
	if page:IsA("GuiObject") then
		local scroll = getScroll(page)
		if scroll then
			for _, card in scroll:GetChildren() do
				if card:IsA("GuiObject") then
					wireCard(page, card)
				end
			end
		end

		local favBtn = page:FindFirstChild("FavoriteButton", true)
		if favBtn then
			favBtn.Activated:Connect(function()
				toggleFavorite(page)
			end)
		end

		local execBtn = page:FindFirstChild("ExecuteButton", true)
		if execBtn then
			execBtn.Activated:Connect(function()
				local card = selected[page.Name]
				local title = card and card:FindFirstChild("Title")
				print("Execute:", title and plain(title.Text) or "ничего не выбрано")
			end)
		end

		-- ПОИСК: фильтруем карточки по названию
		local bar = page:FindFirstChild("SearchBar")
		local box = bar and bar:FindFirstChildWhichIsA("TextBox", true)
		if box and scroll then
			box:GetPropertyChangedSignal("Text"):Connect(function()
				local q = box.Text:lower()
				for _, card in scroll:GetChildren() do
					if card:IsA("GuiObject") then
						local title = card:FindFirstChild("Title")
						local name = title and plain(title.Text):lower() or ""
						card.Visible = (q == "") or (name:find(q, 1, true) ~= nil)
					end
				end
			end)
		end
	end
end

end)

__runLocal(LocalScript, function(script)
local Players = game:GetService("Players")
local player = Players.LocalPlayer

local home = script.Parent -- страница Home

------------------------------------------------
-- ПРИВЕТСТВИЕ ПО ВРЕМЕНИ СУТОК (как в 7.150: "Good Evening, ...")
------------------------------------------------
local welcome = home:FindFirstChild("WelcomeMessage")
if welcome then
	local hour = tonumber(os.date("%H"))
	local g
	if hour >= 5 and hour < 12 then
		g = "Good Morning"
	elseif hour >= 12 and hour < 18 then
		g = "Good Afternoon"
	elseif hour >= 18 and hour < 23 then
		g = "Good Evening"
	else
		g = "Good Night"
	end
	welcome.Text = g .. ","
end

------------------------------------------------
-- ИМЯ И НИК
------------------------------------------------
local nameLabel = home:FindFirstChild("PlayerName")
local userLabel = home:FindFirstChild("PlayerUser")
if nameLabel then nameLabel.Text = player.DisplayName .. "!" end
if userLabel then userLabel.Text = "@" .. player.Name end

------------------------------------------------
-- АВАТАРКА
------------------------------------------------
local avatarFrame = home:FindFirstChild("PLayersAvatarHome")
if avatarFrame then
	local img = avatarFrame:FindFirstChildWhichIsA("ImageLabel", true)
	if not img then
		img = Instance.new("ImageLabel")
		img.Name = "AvatarImage"
		img.Parent = avatarFrame
	end
	img.Position = UDim2.new(0, 0, 0, 0)
	img.Size = UDim2.new(1, 0, 1, 0)
	img.BackgroundTransparency = 1
	img.ScaleType = Enum.ScaleType.Crop
	img.ZIndex = 3
	avatarFrame.ClipsDescendants = true -- картинка обрежется по скруглённой рамке
	img.Image = Players:GetUserThumbnailAsync(
		player.UserId,
		Enum.ThumbnailType.HeadShot,
		Enum.ThumbnailSize.Size180x180
	)
end

end)

__runLocal(AvatarLoader, function(script)
