__runLocal(LocalScript_727, function(script)
local UIS = game:GetService("UserInputService")

local topBar = script.Parent           -- фрейм "Discord, Close and Settings"
local gui = topBar.Parent              -- ScreenGui "VexHub"
topBar.Active = true

local anim = __hubRequire(gui:WaitForChild("Animation"))

------------------------------------------------
-- КРЕСТИК: закрыть гуишку (с анимацией испарения)
------------------------------------------------
local closeLogo = topBar["Close And Settings"].CloseLogo

local click = closeLogo:FindFirstChild("ClickZone")
if not click then
	click = Instance.new("TextButton")
	click.Name = "ClickZone"
	click.BackgroundTransparency = 1
	click.Text = ""
	click.Size = UDim2.fromScale(1, 1)
	click.ZIndex = 10
	click.Parent = closeLogo
end

click.Activated:Connect(function()
	anim.close()
end)

-- RightShift: показать/скрыть
UIS.InputBegan:Connect(function(input, gpe)
	if gpe then return end
	if input.KeyCode == Enum.KeyCode.RightShift then
		anim.toggle()
	end
end)

------------------------------------------------
-- ПЕРЕТАСКИВАНИЕ окна за шапку
------------------------------------------------
local dragging = false
local dragStart
local startPos = {}

topBar.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1
	or input.UserInputType == Enum.UserInputType.Touch then
		dragging = true
		dragStart = input.Position
		table.clear(startPos)
		for _, v in gui:GetChildren() do
			if v:IsA("GuiObject") then
				startPos[v] = v.Position
			end
		end
		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then
				dragging = false
			end
		end)
	end
end)

UIS.InputChanged:Connect(function(input)
	if not dragging then return end
	if input.UserInputType ~= Enum.UserInputType.MouseMovement
	and input.UserInputType ~= Enum.UserInputType.Touch then return end

	local delta = input.Position - dragStart
	for v, pos in pairs(startPos) do
		v.Position = UDim2.new(
			pos.X.Scale, pos.X.Offset + delta.X,
			pos.Y.Scale, pos.Y.Offset + delta.Y
		)
	end
end)

end)

__runLocal(LocalScript_742, function(script)
local gui = script:FindFirstAncestorOfClass("ScreenGui")
local content = gui.MainWindow:WaitForChild("Content")

-- фрейм таба -> имя страницы внутри Content
local tabs = {
	TabHome = "Home",
	TabScripts = "Scripts",
	TabGUIS = "GUIS",
	TabFavorites = "Favorites",
	TabAnimations = "Animations",
	TabCommands = "Commands",
	TabOtherHubs = "OtherHubs",
	TabLimitedScripts = "LimitedScripts",
}

local ACTIVE = Color3.fromRGB(255, 255, 255)
local IDLE   = Color3.fromRGB(90, 90, 90)

local function showPage(pageName)
	local target = content:FindFirstChild(pageName)
	if not target then return end -- страницы нет (Home сделаешь позже) — ничего не трогаем
	for _, page in content:GetChildren() do
		if page:IsA("GuiObject") then
			page.Visible = (page.Name == pageName)
		end
	end
	-- подсветка активного таба (ищем рекурсивно, табы лежат во вложенном ScrollingFrame)
	for tabName, pName in pairs(tabs) do
		local tab = script.Parent:FindFirstChild(tabName, true)
		local stroke = tab and tab:FindFirstChildWhichIsA("UIStroke")
		if stroke then
			stroke.Color = (pName == pageName) and ACTIVE or IDLE
		end
	end
end

for tabName, pageName in pairs(tabs) do
	local tab = script.Parent:FindFirstChild(tabName, true)
	local button = tab and tab:FindFirstChildWhichIsA("GuiButton", true)
	if button then
		button.Activated:Connect(function()
			showPage(pageName)
		end)
	end
end

showPage("Home") -- стартовая страница

end)

end


