__runLocal(Loader, function(script)
local TweenService = game:GetService("TweenService")
local Players = game:GetService("Players")
local Lighting = game:GetService("Lighting")

print("[VHubLoader] загрузка началась")

local playerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
local gui = script.Parent

local root = gui:WaitForChild("Root")
local logo = root:WaitForChild("Logo")
local barFill = root:WaitForChild("BarBack"):WaitForChild("BarFill")
local statusLabel = root:WaitForChild("Status")
local percentLabel = root:WaitForChild("Percent")
local scale = root:FindFirstChildWhichIsA("UIScale")

------------------------------------------------
-- прячем всё для плавного появления
------------------------------------------------
local originals = {}
for _, v in gui:GetDescendants() do
	local props = {}
	if v:IsA("GuiObject") then props.BackgroundTransparency = v.BackgroundTransparency end
	if v:IsA("TextLabel") or v:IsA("TextButton") or v:IsA("TextBox") then props.TextTransparency = v.TextTransparency end
	if v:IsA("ImageLabel") or v:IsA("ImageButton") then props.ImageTransparency = v.ImageTransparency end
	if v:IsA("UIStroke") then props.Transparency = v.Transparency end
	if next(props) then
		originals[v] = props
		for k in pairs(props) do v[k] = 1 end
	end
end

local function fadeAll(mode, t)
	for v, props in pairs(originals) do
		local dest = {}
		for k, orig in pairs(props) do
			dest[k] = (mode == "out") and 1 or orig
		end
		TweenService:Create(v, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), dest):Play()
	end
end

------------------------------------------------
-- блюр фона + появление
------------------------------------------------
local blur = Instance.new("BlurEffect")
blur.Name = "VHubLoaderBlur"
blur.Size = 0
blur.Parent = Lighting
TweenService:Create(blur, TweenInfo.new(0.5), {Size = 14}):Play()
if scale then
	TweenService:Create(scale, TweenInfo.new(0.45, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
end
fadeAll("in", 0.4)
task.wait(0.45)

------------------------------------------------
-- шкала + проценты + ВРАЩЕНИЕ логотипа (полный оборот к 100%)
------------------------------------------------
local progress = Instance.new("NumberValue")
progress.Value = 0
progress.Changed:Connect(function(v)
	barFill.Size = UDim2.fromScale(v / 100, 1)
	percentLabel.Text = tostring(math.floor(v + 0.5)) .. "%"
	logo.Rotation = v * 3.6
end)

-- ЧТО ГРУЗИМ (строка статуса) — редактируй тут
local steps = {
	"Initializing core",
	"Loading Home",
	"Loading Favorites",
	"Loading Scripts",
	"Loading GUIS",
	"Loading Animations",
	"Loading Commands",
	"Loading Other Hubs",
	"Loading Limited Scripts",
	"Preparing open button",
	"Finalizing",
}

local currentStatus = ""
local loading = true
task.spawn(function() -- бегущие точки в конце строки
	local dots = {".", "..", "..."}
	local i = 0
	while loading do
		i = i + 1
		statusLabel.Text = currentStatus .. dots[(i % 3) + 1]
		task.wait(0.25)
	end
end)

for i, name in ipairs(steps) do
	currentStatus = name
	local t = TweenService:Create(
		progress,
		TweenInfo.new(0.3 + math.random() * 0.25, Enum.EasingStyle.Linear),
		{Value = i / #steps * 100}
	)
	t:Play()
	t.Completed:Wait()
end

loading = false
statusLabel.Text = "Done!"
task.wait(0.3)

------------------------------------------------
-- финал: СНАЧАЛА кнопка открытия, ПОТОМ сама гуишка
------------------------------------------------
TweenService:Create(blur, TweenInfo.new(0.45), {Size = 0}):Play()

-- 1) кнопка открытия появляется первой
pcall(function()
	local ob = playerGui:FindFirstChild("OpenButton")
	if ob and not ob.Enabled then
		ob.Enabled = true
	end
end)
task.wait(0.35)

-- 2) сама гуишка VexHub — с анимацией появления (окно -> шапка -> табы)
local openStarted = false
local openDone = false
pcall(function()
	local vh = playerGui:FindFirstChild("VexHub")
	if vh and not vh.Enabled then
		local anim = vh:FindFirstChild("Animation")
		if anim then
			openStarted = true
			task.spawn(function()
				__hubRequire(anim).open()
				openDone = true
			end)
		else
			vh.Enabled = true
		end
	end
end)

fadeAll("out", 0.45)

-- ВАЖНО: ждём конца анимации открытия ПЕРЕД самоуничтожением.
-- Уничтожение скрипта убивает его потоки — умрём раньше,
-- и открытие оборвётся на середине (это и был тот баг).
if openStarted then
	local t0 = os.clock()
	while not openDone and os.clock() - t0 < 3 do
		task.wait()
	end
end

blur:Destroy()
gui:Destroy()

end)

end
